package app.morphe.extension.chmate;

import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.*;import android.media.MediaMetadataRetriever;import android.view.*;import android.widget.*;import android.text.*;
import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Local-only, virtualized cache browser; no network or original-post deletion. */
public final class StorageMediaActivity extends HaiagaruComposeActivity {
    private final ExecutorService io=Executors.newSingleThreadExecutor(),thumbs=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(40),new ThreadPoolExecutor.DiscardPolicy());
    private final List<Item> all=new ArrayList<>(),shown=new ArrayList<>();private final Set<String> selected=new HashSet<>();
    private final android.util.LruCache<String,Bitmap> images=new android.util.LruCache<String,Bitmap>(6*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}};
    private Spinner sorting;private int sortMode;private int background,foreground;private EditText query;private TextView status;private CheckBox imageFilter,videoFilter,previews,allCheck;private BaseAdapter adapter;private boolean updating,dead;private int generation;
    static void open(Activity a){a.startActivity(new Intent(a,StorageMediaActivity.class));}
    @Override public void onCreate(Bundle b){super.onCreate(b);int[] palette=HaiagaruUi.toolTabHeaderColors(this);background=palette[0];foreground=palette[1];sortMode=getPreferences(0).getInt("sort",0);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setBackgroundColor(background);setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(12),dp(8)+insets.getSystemWindowInsetTop(),dp(12),dp(8)+insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
        TextView title=new TextView(this);title.setText("‹ 保存画像・動画の管理");title.setOnClickListener(v->finish());title.setPadding(0,dp(8),0,dp(8));title.setTextSize(20);title.setTextColor(foreground);root.addView(title);
        query=new EditText(this);query.setSingleLine(true);query.setHint("ファイル名・保存場所で検索");query.setTextColor(foreground);query.setHintTextColor((foreground&0xffffff)|0x99000000);root.addView(query);
        LinearLayout filters=new LinearLayout(this);imageFilter=check(filters,"画像",true);videoFilter=check(filters,"動画",true);previews=check(filters,"サムネイル",true);root.addView(filters);
        sorting=new Spinner(this);String[] sortLabels={"容量：大きい順（降順）","容量：小さい順（昇順）","日付：新しい順（降順）","日付：古い順（昇順）","名前：昇順","名前：降順"};
        ArrayAdapter<String> sortAdapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,sortLabels){@Override public View getView(int pos,View view,ViewGroup parent){TextView label=(TextView)super.getView(pos,view,parent);label.setTextColor(foreground);return label;}@Override public View getDropDownView(int pos,View view,ViewGroup parent){TextView label=(TextView)super.getDropDownView(pos,view,parent);label.setTextColor(foreground);label.setBackgroundColor(background);label.setPadding(dp(16),dp(16),dp(16),dp(16));return label;}};
        sorting.setAdapter(sortAdapter);sorting.setSelection(Math.max(0,Math.min(5,sortMode)));root.addView(sorting);sorting.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){sortMode=position;getPreferences(0).edit().putInt("sort",position).apply();filter();}public void onNothingSelected(AdapterView<?> p){}});
        LinearLayout actions=new LinearLayout(this);allCheck=check(actions,"全て選択",false);Button remove=new Button(this);remove.setText("選択を削除");actions.addView(remove);Button reload=new Button(this);reload.setText("再集計");actions.addView(reload);root.addView(actions);styleButton(remove);styleButton(reload);
        status=new TextView(this);status.setTextColor(foreground);root.addView(status);TextView help=new TextView(this);help.setTextColor(foreground);help.setText("日付はキャッシュファイルの更新日時です。チェックで選択、画像をタップで拡大／動画をタップで再生。全選択は検索・種類で絞った一覧が対象です。端末内キャッシュのみで、URL検索や通信はしません。");root.addView(help);
        ListView list=new ListView(this);list.setVerticalScrollBarEnabled(true);list.setFastScrollEnabled(true);list.setFastScrollAlwaysVisible(true);list.setScrollBarStyle(View.SCROLLBARS_INSIDE_OVERLAY);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));adapter=new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int pos,View recycled,android.view.ViewGroup parent){
            LinearLayout row=recycled instanceof LinearLayout?(LinearLayout)recycled:new LinearLayout(StorageMediaActivity.this);
            if(row.getChildCount()==0){row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(4),dp(8),dp(4),dp(8));row.addView(new CheckBox(StorageMediaActivity.this));ImageView image=new ImageView(StorageMediaActivity.this);image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);row.addView(image,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView text=new TextView(StorageMediaActivity.this);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));}
            Item item=shown.get(pos);CheckBox toggle=(CheckBox)row.getChildAt(0);toggle.setOnCheckedChangeListener(null);toggle.setChecked(selected.contains(item.key));toggle.setContentDescription("選択 "+item.file.getName());toggle.setOnCheckedChangeListener((v,on)->{if(on)selected.add(item.key);else selected.remove(item.key);selection();});
            TextView text=(TextView)row.getChildAt(2);text.setTextColor(foreground);text.setTextSize(14);row.setBackgroundColor(background);text.setText((item.video?"▶ 動画":"画像")+"  "+item.file.getName()+"\n"+android.text.format.Formatter.formatFileSize(StorageMediaActivity.this,item.bytes)+"\n"+android.text.format.DateFormat.format("yyyy/MM/dd HH:mm",item.modified)+"\n"+item.file.getParent());
            ImageView image=(ImageView)row.getChildAt(1);image.setTag(item.key);image.setImageDrawable(null);image.setVisibility(previews.isChecked()?View.VISIBLE:View.GONE);if(previews.isChecked())thumbnail(item,image);row.setOnClickListener(v->view(item));return row;
        }};list.setAdapter(adapter);
        query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){filter();}public void afterTextChanged(Editable e){}});
        imageFilter.setOnCheckedChangeListener((v,on)->filter());videoFilter.setOnCheckedChangeListener((v,on)->filter());previews.setOnCheckedChangeListener((v,on)->{generation++;adapter.notifyDataSetChanged();});
        allCheck.setOnCheckedChangeListener((v,on)->{if(updating)return;for(Item i:shown){if(on)selected.add(i.key);else selected.remove(i.key);}adapter.notifyDataSetChanged();selection();});remove.setOnClickListener(v->removeSelected());reload.setOnClickListener(v->scan());scan();
    }
    private void styleButton(Button b){b.setAllCaps(false);b.setTextSize(14);b.setTextColor(foreground);b.setMinHeight(dp(48));android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(background);shape.setCornerRadius(dp(18));shape.setStroke(dp(1),(foreground&0xffffff)|0x66000000);b.setBackground(shape);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(4),dp(4),dp(4),dp(4));b.setLayoutParams(lp);}
    private CheckBox check(LinearLayout p,String label,boolean value){CheckBox c=new CheckBox(this);c.setText(label);c.setTextColor(foreground);c.setButtonTintList(android.content.res.ColorStateList.valueOf(foreground));c.setChecked(value);p.addView(c);return c;}
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
    private void scan(){status.setText("画像・動画を集計中…");io.execute(()->{List<Item> result=scanFiles(this);runOnUiThread(()->{if(dead)return;all.clear();all.addAll(result);selected.retainAll(keys(result));filter();});});}
    private static Set<String> keys(List<Item> items){Set<String> keys=new HashSet<>();for(Item i:items)keys.add(i.key);return keys;}
    static List<Item> scanFiles(Context c){List<Item> found=new ArrayList<>();List<File> roots=new ArrayList<>();File[] external=c.getExternalFilesDirs(null);if(external!=null)for(File f:external)if(f!=null)roots.add(new File(f,"2chMate/media"));roots.add(c.getCacheDir());Set<String> visited=new HashSet<>();ArrayDeque<File> pending=new ArrayDeque<>(roots);int count=0;
        while(!pending.isEmpty()&&count++<100000&&found.size()<10000){File f=pending.pop();try{String path=f.getCanonicalPath();if(!StorageUsage.deletionAllowed(c,f)&&!roots.contains(f)||!visited.add(path))continue;File parent=f.getParentFile();if(parent!=null&&!new File(parent.getCanonicalFile(),f.getName()).getAbsolutePath().equals(path))continue;if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)Collections.addAll(pending,children);}else{int type=kind(f);if(type!=0)found.add(new Item(f,path,type==2));}}catch(Exception ignored){}}
        found.sort((a,b)->Long.compare(b.bytes,a.bytes));return found;
    }
    static int kind(File f){try(FileInputStream in=new FileInputStream(f)){byte[] h=new byte[32];int n=in.read(h);if(n<12)return 0;
        if((h[0]&255)==255&&(h[1]&255)==216||h[0]==(byte)137&&h[1]==80&&h[2]==78&&h[3]==71||h[0]=='G'&&h[1]=='I'&&h[2]=='F'||h[0]=='R'&&h[8]=='W'&&h[9]=='E'&&h[10]=='B'&&h[11]=='P')return 1;
        if(h[4]=='f'&&h[5]=='t'&&h[6]=='y'&&h[7]=='p'){String brand=new String(h,8,4,java.nio.charset.StandardCharsets.US_ASCII);return brand.startsWith("avif")||brand.startsWith("hei")?1:2;}
        if(h[0]==0x1a&&h[1]==0x45&&h[2]==(byte)0xdf&&h[3]==(byte)0xa3)return 2;
    }catch(IOException ignored){}return 0;}
    private void filter(){if(adapter==null)return;String q=query.getText().toString().toLowerCase(Locale.ROOT);shown.clear();for(Item i:all)if((i.video?videoFilter.isChecked():imageFilter.isChecked())&&i.key.toLowerCase(Locale.ROOT).contains(q))shown.add(i);sort(shown,sortMode);adapter.notifyDataSetChanged();selection();}
    static void sort(List<Item> items,int mode){
        Comparator<Item> order=mode==1?Comparator.comparingLong(i->i.bytes):mode==2?Comparator.comparingLong((Item i)->i.modified).reversed():mode==3?Comparator.comparingLong(i->i.modified):mode==4?Comparator.comparing(i->i.file.getName(),String.CASE_INSENSITIVE_ORDER):mode==5?Comparator.comparing((Item i)->i.file.getName(),String.CASE_INSENSITIVE_ORDER).reversed():Comparator.comparingLong((Item i)->i.bytes).reversed();items.sort(order.thenComparing(i->i.key));
    }
    private void selection(){long bytes=0;int n=0;for(Item i:shown)if(selected.contains(i.key)){n++;bytes+=i.bytes;}updating=true;allCheck.setChecked(!shown.isEmpty()&&n==shown.size());updating=false;status.setText(shown.size()+"件 ／ 選択 "+n+"件・"+android.text.format.Formatter.formatFileSize(this,bytes)+"（最大1万件）");}
    private void thumbnail(Item item,ImageView image){Bitmap cached=images.get(item.key);if(cached!=null){image.setImageBitmap(cached);return;}int gen=generation;java.lang.ref.WeakReference<ImageView> target=new java.lang.ref.WeakReference<>(image);
        thumbs.execute(()->{if(dead||gen!=generation)return;ImageView slot=target.get();if(slot==null||!item.key.equals(slot.getTag()))return;Bitmap bitmap=decode(item,dp(96));if(bitmap==null)return;images.put(item.key,bitmap);runOnUiThread(()->{ImageView v=target.get();if(!dead&&gen==generation&&v!=null&&item.key.equals(v.getTag()))v.setImageBitmap(bitmap);});});
    }
    private static Bitmap decode(Item item,int size){try{if(item.video){MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(item.file.getAbsolutePath());if(Build.VERSION.SDK_INT>=27)return r.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,size,size);
            Bitmap frame=r.getFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);if(frame==null)return null;float ratio=Math.min(1f,Math.min((float)size/frame.getWidth(),(float)size/frame.getHeight()));if(ratio>=1f)return frame;Bitmap small=Bitmap.createScaledBitmap(frame,Math.max(1,(int)(frame.getWidth()*ratio)),Math.max(1,(int)(frame.getHeight()*ratio)),true);if(small!=frame)frame.recycle();return small;}finally{r.release();}}
        BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(item.key,o);o.inSampleSize=1;while(o.outWidth/o.inSampleSize>size*2||o.outHeight/o.inSampleSize>size*2)o.inSampleSize*=2;o.inJustDecodeBounds=false;return BitmapFactory.decodeFile(item.key,o);
    }catch(Exception|OutOfMemoryError ignored){return null;}}
    private void view(Item item){if(item.video){Dialog d=new Dialog(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);VideoView video=new VideoView(this);box.addView(video,new LinearLayout.LayoutParams(-1,dp(320)));MediaController controls=new MediaController(this);video.setMediaController(controls);video.setVideoPath(item.key);video.setOnPreparedListener(p->video.start());video.setOnErrorListener((p,w,e)->{Toast.makeText(this,"この動画形式を再生できません",Toast.LENGTH_LONG).show();return true;});d.setContentView(box);d.setOnDismissListener(v->video.stopPlayback());d.show();d.getWindow().setLayout(-1,-2);}
        else{io.execute(()->{Bitmap b=decode(item,1024);runOnUiThread(()->{if(dead||b==null)return;ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(b);new AlertDialog.Builder(this).setTitle(item.file.getName()).setView(image).setPositiveButton("閉じる",null).show();});});}}
    private void removeSelected(){List<Item> targets=new ArrayList<>();for(Item i:shown)if(selected.contains(i.key))targets.add(i);if(targets.isEmpty())return;new AlertDialog.Builder(this).setTitle(targets.size()+"件のキャッシュを削除しますか？").setMessage("再表示時は再取得の通信が発生します。接続先から消えたファイルは再取得できません。元のレスは削除しません。").setNegativeButton("キャンセル",null).setPositiveButton("削除",(d,w)->io.execute(()->{int removed=0;for(Item i:targets)if(StorageUsage.deleteCache(this,i.file)>=0)removed++;final int n=removed;runOnUiThread(()->{if(!dead){Toast.makeText(this,n+"件を削除しました",Toast.LENGTH_LONG).show();images.evictAll();selected.clear();scan();}});})).show();}
    @Override public void onDestroy(){dead=true;generation++;io.shutdownNow();thumbs.shutdownNow();images.evictAll();super.onDestroy();}
    static final class Item{final File file;final String key;final boolean video;final long bytes,modified;Item(File f,String k,boolean v){file=f;key=k;video=v;bytes=f.length();modified=f.lastModified();}}
}
